async function executeDiagnoseProject(logger2, detection, workspace12, clangdOps) {
  logger2.info("[diagnoseProject] invoked");
  const project = await resolveProjectOrPick({
    detection,
    workspace: workspace12,
    warningKey: "diagnoseProject.noProject"
  });
  if (!project) {
    return;
  }
  const report = await diagnoseProject(project.path, workspace12, clangdOps);
  const formatted = formatDiagnosticReport(report);
  logger2.info(formatted);
  logger2.show();
  const message = report.overallStatus === "ok" ? t("diagnoseProject.summary.ok") : t("diagnoseProject.summary.failed", {
    count: String(report.checks.filter((check) => check.status === "fail").length)
  });
  void vscode47.window.showInformationMessage(message, t("showInfo.openOutput"));
}

